// دفاع Node.js: تعطيل معالجة الكيانات الخارجية والـ DTD كليًّا
const parser = new XMLParser({
  processEntities: false,   // لا تحلّ أي كيان خارجي
  allowBooleanAttributes: true,
});

// القاعدة العامة بأي لغة: عطّل DTD والكيانات الخارجية
// كخطوة إعداد افتراضية لأي محلّل XML يعالج مدخلات مستخدمين

// ترويسة تمنع تضمين صفحتك داخل أي إطار خارجي
response.setHeader(
  "Content-Security-Policy",
  "frame-ancestors 'self'"   // اسمح بالتضمين من نفس نطاقك فقط
);

// أو الترويسة الأقدم المكافئة
response.setHeader("X-Frame-Options", "SAMEORIGIN");

// ✅ آمن: تحقّق من الوجهة مقابل قائمة بيضاء من المسارات الداخلية فقط
function safeRedirectTarget(next) {
  if (typeof next !== "string") return "/";
  if (!next.startsWith("/") || next.startsWith("//")) return "/"; // لا روابط خارجية
  return next;
}

res.redirect(safeRedirectTarget(req.query.next));

// ✅ آمن: طابق الاسم مقابل قائمة معروفة، لا تبنِ مسارًا من مدخل حرّ
const ALLOWED_FILES = new Map([
  ["invoice-2024", "/secure-storage/invoice-2024.pdf"],
]);

function resolveFile(name) {
  return ALLOWED_FILES.get(name) ?? null; // غير موجود في القائمة = مرفوض
}

const filePath = resolveFile(req.query.name);
if (!filePath) return res.status(404).end();

// ✅ آمن: مرّر الوسيطة كعنصر منفصل، لا كنصّ مدموج يفسَّره الشِل
const { execFile } = require("node:child_process");

execFile("convert", [inputPath, outputPath], (err, stdout) => {
  // execFile لا يمرّ عبر الشِل — الوسائط لا تُفسَّر كأوامر إضافية
});

// ✅ آمن: استخرج الحقول المسموحة صراحة (allowlist) قبل التحديث
function pickAllowedFields(body) {
  const { displayName, bio } = body;   // فقط ما يُسمح للمستخدم بتعديله
  return { displayName, bio };
}

await User.update(user.id, pickAllowedFields(req.body));
// role وisAdmin غير موجودين هنا مهما أرسل الطلب — غير قابلين للتعديل من هذا المسار

// ✅ آمن: خطوتان منفصلتان وصريحتان دائمًا — لا تُنهِ المعالجة عند نجاح فكّ التشفير فقط
const decryptedPayload = decryptJWE(token, privateKey);

// تحقّق من توقيع المحتوى الداخلي كأي JWT مستقلّ، بخوارزمية مفروضة صراحة
const verifiedClaims = jwt.verify(decryptedPayload, publicKey, {
  algorithms: ["RS256"], // نفس فرض الخوارزمية المستخدَم لأي JWT عادي
});
// لا تثق بادّعاءات verifiedClaims قبل نجاح هذه الخطوة الثانية بالتحديد

// ✅ آمن: كوكي جلسة بخصائص الحماية الثلاث معًا
res.cookie("sessionId", token, {
  httpOnly: true,   // غير مقروء من JavaScript — يحدّ من سرقته عبر XSS
  secure: true,     // يُرسَل فقط عبر HTTPS
  sameSite: "strict",
});

// وعند نجاح تسجيل الدخول: أصدر معرّف جلسة جديدًا دائمًا
// بدل إعادة استخدام أي معرّف كان موجودًا قبل المصادقة

// ✅ آمن: خوارزمية تجزئة حديثة تُضمّن salt فريدًا تلقائيًّا لكل استدعاء
const bcrypt = require("bcrypt");

const hashed = await bcrypt.hash(password, 12); // salt عشوائي مضمَّن تلقائيًّا
const isValid = await bcrypt.compare(inputPassword, hashed);
// كل مستخدم يحصل على salt مختلف حتى لو كانت كلمة المرور نفسها

// ✅ آمن: تأخير متزايد + سقف طلبات لكل IP، بدل قفل حساب فوري وصارم
const rateLimiter = new Map(); // بمثال حقيقي: استخدم Redis لا ذاكرة العملية

function checkRateLimit(ip) {
  const attempts = rateLimiter.get(ip) ?? 0;
  if (attempts > 10) return false;  // تجاوز السقف خلال النافذة الزمنية
  rateLimiter.set(ip, attempts + 1);
  return true;
}

if (!checkRateLimit(req.ip)) return res.status(429).send("حاول لاحقًا");

// لا يوجد "كود دفاعي" مباشر ضدّ ثغرة مجهولة بحكم تعريفها —
// الممارسة الوقائية هي تقليل الأثر ببنية النظام نفسها:

// 1) طبّق تحديثات الأمان فور صدورها تلقائيًّا حيث أمكن
// 2) قلّل صلاحيات كل مكوّن لأقلّ ما يلزم (أقل صلاحية)
// 3) اعزل المكوّنات الحسّاسة عن بعضها (دفاع متعدّد الطبقات)
// بحيث لو استُغلّت ثغرة مجهولة بمكوّن واحد، لا تنكشف بقية النظام تلقائيًّا

// ✅ آمن: تحقّق من نطاق الطلب مقابل قائمة بيضاء صريحة قبل الردّ
const ALLOWED_ORIGINS = new Set(["https://app.example.com"]);

const origin = req.headers.origin;
if (ALLOWED_ORIGINS.has(origin)) {
  res.setHeader("Access-Control-Allow-Origin", origin);
  res.setHeader("Access-Control-Allow-Credentials", "true");
}
// نطاق غير موجود بالقائمة: لا تُرسَل الترويسة إطلاقًا — المتصفّح يحجب القراءة

